## 🔧 Реализация на JavaScript

```javascript
function countSmallerAfter(arr) {
  // Массив для хранения результатов
  const result = new Array(arr.length).fill(0);

  // Массив для сортировки с подсчётом
  const sorted = [];

  // Обходим массив с конца, чтобы не пересекаться с уже обработанными элементами
  for (let i = arr.length - 1; i >= 0; i--) {
    // Найдём позицию, где можно вставить arr[i], чтобы сохранить отсортированность
    let pos = binarySearch(sorted, arr[i]);

    // Количество элементов, меньших arr[i], это позиция
    result[i] = pos;

    // Вставляем arr[i] в отсортированный массив
    sorted.splice(pos, 0, arr[i]);
  }

  return result;
}

// Функция двоичного поиска для отсортированного массива
function binarySearch(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return left;
}
```

